import json

class StakeholderInterview:
    def __init__(self, name, role, responses):
        self.name = name
        self.role = role
        self.responses = responses

    def to_dict(self):
        return {"name": self.name, "role": self.role, "responses": self.responses}

def conduct_interviews(participants):
    interviews = []
    for participant in participants:
        responses = {
            "requirements": input(f"{participant['name']} ({participant['role']}): What are your key requirements? "),
            "privacy_concerns": input(f"{participant['name']} ({participant['role']}): What are your data privacy concerns? ")
        }
        interviews.append(StakeholderInterview(participant['name'], participant['role'], responses).to_dict())
    return interviews

# Example participants
participants = [
    {"name": "Teacher1", "role": "Teacher"},
    {"name": "Teacher2", "role": "Teacher"},
    {"name": "Student1", "role": "Student"},
    {"name": "Student2", "role": "Student"},
    {"name": "Admin1", "role": "Administrator"}
]

# Conduct interviews
interview_results = conduct_interviews(participants)

# Save results to JSON
with open("interview_results.json", "w") as f:
    json.dump(interview_results, f, indent=4)
